insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
  $x$pm-process-map-intro$x$, $x$tool$x$, $x$milestone$x$, $x$ch1$x$, 5, $x$beginner$x$, 12, 30,
  $x$تمهيد خريطة عمليات إدارة المشاريع$x$,
  $x$رتّب مجموعات العمليات الخمس، وضع عمليات مختارة في مجموعاتها ومجالاتها، ثم اختر العملية التي تعمل في مواقف من المشروع.$x$,
  $x${"story_ar":"الخريطة الكلاسيكية للعمليات من الإصدار السادس لدليل PMBOK: 49 عملية، كل منها عند تقاطع مجال معرفي من عشرة ومجموعة عمليات من خمس. الإصداران السابع والثامن انتقلا إلى «مجالات الأداء» كما يذكر الكتيب، لكن الخريطة تبقى مرجعًا ذهنيًا نافعًا: كل مجال يمر ببدء ثم تخطيط ثم تنفيذ ثم متابعة ثم إغلاق. هذا تمهيد سريع قبل بناء اللوحة كاملة.","role_ar":"مدير مكتب مشاريع جديد يريد أن يرى المشروع كاملًا على ورقة واحدة","closing_ar":"التخطيط أكبر المجموعات، و«الضبط» و«التحكم» و«المتابعة» تقع كلها في عمود المتابعة. ومن الأسماء وحدها تعرف أغلب الخانات: «وضع خطة…» تخطيط، و«إدارة…» تنفيذ، و«ضبط…» و«متابعة…» متابعة.","meters":[],"steps":[{"type":"order","title_ar":"مجموعات العمليات","prompt_ar":"رتّب مجموعات العمليات الخمس كما يمر بها المشروع.","context_ar":"","why_ar":"البدء يأذن بالمشروع، والتخطيط يرسم طريقه، والتنفيذ ينتجه، والمتابعة والتحكم تقيس الانحراف وتصححه طوال الطريق، والإغلاق يسلّمه رسميًا.","weight":1,"items":[{"id":"init","label":"البدء"},{"id":"plan","label":"التخطيط"},{"id":"exec","label":"التنفيذ"},{"id":"mc","label":"المتابعة والتحكم"},{"id":"close","label":"الإغلاق"}],"answer":["init","plan","exec","mc","close"]},{"type":"classify","title_ar":"أين تقع العملية؟","prompt_ar":"ضع كل عملية في مجموعتها.","context_ar":"","why_ar":"اسأل عن كل عملية: هل تأذن بالبدء، أم تُنتج خطة، أم تنفذها، أم تقيس الانحراف عنها، أم تُغلق؟","weight":2,"bins":[{"id":"init","label":"البدء"},{"id":"plan","label":"التخطيط"},{"id":"exec","label":"التنفيذ"},{"id":"mc","label":"المتابعة والتحكم"},{"id":"close","label":"الإغلاق"}],"items":[{"id":"p4-1","label":"وضع ميثاق المشروع","bin":"init","note_ar":"الميثاق يأذن ببدء المشروع، فهو أول عملية في البدء لا في التخطيط."},{"id":"p13-1","label":"تحديد المعنيين","bin":"init","note_ar":"تحديد المعنيين يبدأ مع المشروع، فهو العملية الثانية في عمود البدء مع الميثاق."},{"id":"p5-3","label":"تحديد النطاق","bin":"plan","note_ar":"«تحديد» النطاق تخطيط، أما «التحقق» منه فمتابعة. لا تخلط بينهما."},{"id":"p5-5","label":"التحقق من النطاق","bin":"mc","